+            <h3>Último evento</h3>
+            <div class="metric"><span>Última acción</span><strong id="last_action">sin datos</strong></div>
+            <div class="metric"><span>Último estado</span><strong id="last_status">sin datos</strong></div>
+            <div class="metric"><span>Duración</span><strong><span id="last_duration">sin datos</span> ms</strong></div>
+            <div class="source">
+              Fuente: <code>data/last_event.json</code><br />
+              Estado: <span class="pill real">real</span>
+            </div>
+          </div>
         </div>
       </div>
@@
     <footer>
       Dashboard v2 estático. Si un dato no tiene fuente verificable, se muestra como “sin datos”, “sin snapshot” o “no disponible”.
     </footer>
   </main>
+
+  <script>
+    function renderLastEventFallback() {
+      document.getElementById('last_action').textContent = 'sin datos';
+      document.getElementById('last_status').textContent = 'sin datos';
+      document.getElementById('last_duration').textContent = 'sin datos';
+    }
+
+    function refreshLastEvent() {
+      fetch('data/last_event.json', { cache: 'no-store' })
+        .then(response => {
+          if (!response.ok) throw new Error(`HTTP ${response.status}`);
+          return response.json();
+        })
+        .then(data => {
+          document.getElementById('last_action').textContent = data.action ?? 'sin datos';
+          document.getElementById('last_status').textContent = data.status ?? 'sin datos';
+          document.getElementById('last_duration').textContent = data.duration_ms ?? 'sin datos';
+        })
+        .catch(error => {
+          console.error('Error cargando data/last_event.json:', error);
+          renderLastEventFallback();
+        });
+    }
+
+    refreshLastEvent();
+    setInterval(refreshLastEvent, 5000);
+  </script>
 </body>
 </html>
